import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"Context Group: What the Model Sees This Turn","description":"The next question after the prompt: content. Five topics cover every engineering aspect of what a model sees in a single turn — the hard window budget, assembly strategy, cross-turn sessions, repo conventions. Entry is prompt; exit is a budget you can compute, sources you can assemble, rot you can counter.","frontmatter":{"title":"Context Group: What the Model Sees This Turn","description":"The next question after the prompt: content. Five topics cover every engineering aspect of what a model sees in a single turn — the hard window budget, assembly strategy, cross-turn sessions, repo conventions. Entry is prompt; exit is a budget you can compute, sources you can assemble, rot you can counter.","domain":"tech","tags":["context","index","navigation"],"navOrder":30,"topicId":"context-index","layer":"3","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":["structured-output"],"next":["prompt","context-window","context","session-state","repo-context"],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/03-context/index.md","filePath":"tech/03-context/index.md","lastUpdated":1791169449000}'),a={name:"tech/03-context/index.md"};function i(s,t,d,l,h,c){return o(),n("div",null,[...t[0]||(t[0]=[r(`<blockquote><p><strong>Group</strong>: Context (group guide) | <strong>Previous group exit</strong>: interface contracts and serving shapes | <strong>This group exit</strong>: assemble a single-turn context within budget and manage cross-turn memory</p></blockquote><h1 id="context-group-what-the-model-sees-this-turn" tabindex="-1">Context Group: What the Model Sees This Turn <a class="header-anchor" href="#context-group-what-the-model-sees-this-turn" aria-label="Permalink to &quot;Context Group: What the Model Sees This Turn&quot;">​</a></h1><blockquote><p><strong>Group</strong>: Context group | <strong>Before this group</strong>: can write and validate input/output schemas (<a href="./../02-inference-interface/structured-output.html">structured-output</a>) | <strong>Group exit</strong>: the full chain of &quot;what the model sees this turn&quot; — a budget you can compute, sources you can assemble, rot you can counter <strong>Prerequisites</strong>: <a href="./../02-inference-interface/structured-output.html">structured-output</a> | <strong>Next</strong>: <a href="./../04-grounding/embeddings-retrieval.html">Embeddings and Retrieval</a>, <a href="./../05-action/tool-calling.html">Tool Calling Contract</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Bottom line</strong>: however well the prompt is written, it controls only &quot;how to say&quot;; the other half of quality and cost lies in &quot;<strong>what the model sees</strong>&quot;. The Context group splits that question into five orthogonal sub-questions, one page each: how to express (prompt), how much fits (context-window), what to load (context-engineering), where cross-turn history lives (session-memory), how to declare repo conventions (repo-context).</p><p>Why a whole group: context is a <strong>finite resource with diminishing returns</strong> — the more tokens in the window, the worse the model&#39;s accurate recall (context rot, present across models); meanwhile every resent token is billed. Do input-side curation badly and every layer above (grounded retrieval, tool execution, operations reconciliation) pays for noise.</p><h3 id="mental-model-the-transformation-chain-from-intent-to-window" tabindex="-1">Mental model: the transformation chain from intent to window <a class="header-anchor" href="#mental-model-the-transformation-chain-from-intent-to-window" aria-label="Permalink to &quot;Mental model: the transformation chain from intent to window&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>human intent</span></span>
<span class="line"><span>   │ ① prompt              how to express (task/constraints/examples/output format)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>controlled instruction ── ② context-window      how much fits (token budget, pairs, output reserve)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ ③ context-engineering  what to load (sources, priorities, compaction, staleness)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>assembled window ── ④ session-memory     where history lives (storage, trimming, recovery, concurrency)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼ ⑤ repo-context        how conventions are declared (AGENTS.md, nearest-wins, host injection)</span></span>
<span class="line"><span>what the model actually sees this turn</span></span></code></pre></div><h3 id="symptom-routing-which-page-takes-which-problem" tabindex="-1">Symptom routing: which page takes which problem <a class="header-anchor" href="#symptom-routing-which-page-takes-which-problem" aria-label="Permalink to &quot;Symptom routing: which page takes which problem&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unstable answers, off-target replies (expression)          → prompt</span></span>
<span class="line"><span>400 over-window, linear cost growth, truncated output      → context-window</span></span>
<span class="line"><span>Retrieval stuffed in yet still wrong, stale citations      → context-engineering</span></span>
<span class="line"><span>History lost on refresh, growing amnesia, concurrent bugs  → session-memory</span></span>
<span class="line"><span>Wrong deps / test commands after switching assistants      → repo-context</span></span></code></pre></div><h3 id="topic-navigation-table" tabindex="-1">Topic navigation table <a class="header-anchor" href="#topic-navigation-table" aria-label="Permalink to &quot;Topic navigation table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Topic</th><th>What question it answers</th><th>Exit</th><th>Link</th></tr></thead><tbody><tr><td>Prompt Engineering</td><td>How to turn intent into an executable instruction?</td><td>Write four-element prompts managed as code</td><td><a href="./prompt.html">prompt</a></td></tr><tr><td>Context Window</td><td>How much fits this turn?</td><td>Compute four-block budgets, spot overflow, trim with pairs intact</td><td><a href="./context-window.html">context-window</a></td></tr><tr><td>Context Engineering</td><td>What should be loaded this turn?</td><td>Design multi-source assembly: priorities, visible eviction, compaction and staleness</td><td><a href="./context-engineering.html">context-engineering</a></td></tr><tr><td>Session and State</td><td>Where does cross-turn history live?</td><td>Build sessions: budget trimming, persistent recovery, concurrency guards</td><td><a href="./session-memory.html">session-memory</a></td></tr><tr><td>Repo Context</td><td>How are repo conventions declared?</td><td>Land an AGENTS.md with real commands and correct layering</td><td><a href="./repo-context.html">repo-context</a></td></tr></tbody></table><h3 id="when-to-enter-this-group-when-not" tabindex="-1">When to enter this group / when not <a class="header-anchor" href="#when-to-enter-this-group-when-not" aria-label="Permalink to &quot;When to enter this group / when not&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Audience</strong></td><td>Frontend / full-stack engineers wiring models into products or workflows who start caring about quality and cost</td></tr><tr><td><strong>Enter</strong></td><td>The prompt is clear, but any of these appear: multiple turns, external content (files / retrieval / tool results), coding assistants</td></tr><tr><td><strong>Do not enter</strong></td><td>Answers still unstable or unparseable — close the contract loop first at <a href="./../02-inference-interface/structured-output.html">structured-output</a>; model internals → Learn LLM</td></tr><tr><td><strong>Not this group</strong></td><td>Building the retrieval index → <a href="./../04-grounding/">grounding group</a>; executing actions safely → <a href="./../05-action/tool-calling.html">tool-calling</a></td></tr></tbody></table><h3 id="decision-table-how-the-five-topics-divide-the-work" tabindex="-1">Decision table: how the five topics divide the work <a class="header-anchor" href="#decision-table-how-the-five-topics-divide-the-work" aria-label="Permalink to &quot;Decision table: how the five topics divide the work&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>prompt</th><th>context-window</th><th>context-engineering</th><th>session-memory</th><th>repo-context</th></tr></thead><tbody><tr><td><strong>Controls</strong></td><td>Expression of instructions</td><td>Capacity of input</td><td>Content selection of input</td><td>Cross-turn history I/O</td><td>Repo-level conventions</td></tr><tr><td><strong>Direction</strong></td><td>Human → model (intent)</td><td>System → window (budget)</td><td>Sources → window (curation)</td><td>Session → store → window</td><td>Repo → host → window</td></tr><tr><td><strong>Control</strong></td><td>Text, fully yours</td><td>Assembly layer, fully yours</td><td>Assembly layer, fully yours</td><td>Store implementation, yours</td><td>Repo file + host reading</td></tr><tr><td><strong>State</strong></td><td>Versioned text</td><td>Recomputed per turn</td><td>Reassembled per turn</td><td>Persistent across requests</td><td>Evolves with the repo</td></tr><tr><td><strong>Trust domain</strong></td><td>Diffable</td><td>Estimate vs exact counting</td><td>Source freshness</td><td>Storage and concurrency</td><td>Command truthfulness</td></tr><tr><td><strong>Min complexity</strong></td><td>Lowest, always try first</td><td>Low (single turn) to medium (multi-turn)</td><td>Medium</td><td>Medium (+ persistence)</td><td>Low (one text file)</td></tr></tbody></table><p>Read in navOrder: prompt → context-window → context-engineering → session-memory → repo-context.</p><p><strong>Historical milestones</strong>: unverified (vendor-capability timelines live on each topic page; this page repeats none).</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>This page is navigation and has no standalone fixture — the group&#39;s unified hands-on exit is <a href="./context-window.html">context-window</a>&#39;s zero-key budget allocator (15 minutes: four-block planning → overflow alarm → pair-preserving trim, negative case included). It is the group&#39;s meeting point: the prompt occupies the system block, history the history block, retrieval the retrieval block, output the output reserve — five topics converge on one budget sheet.</p><p><strong>15-minute self-check</strong> (after running the fixture):</p><ol><li>Why must the output reserve count toward the budget? (A: input and output share the window; without a reserve, <code>stop_reason: max_tokens</code> truncates)</li><li>Which two kinds of messages must trimming never sever? (A: the system head; <code>tool_use</code> / <code>tool_result</code> pairs)</li><li>What is the first action when over budget? (A: evict the lowest-priority source visibly — not silently, and not by switching to a bigger-window model)</li></ol><p>Answer all three and the front half of the group&#39;s exit is met; then run <a href="./context-engineering.html">context-engineering</a>&#39;s assembler to add &quot;sources have priorities, eviction is visible&quot;.</p><p><strong>Acceptance command</strong> (the deterministic acceptance of context-window):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx@4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> context-window.ts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BUDGET-OK</span></span></code></pre></div><p><strong>Cleanup</strong>: delete temporary files.</p><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-context-deserves-its-own-group" tabindex="-1">Why &quot;context&quot; deserves its own group <a class="header-anchor" href="#why-context-deserves-its-own-group" aria-label="Permalink to &quot;Why &quot;context&quot; deserves its own group&quot;">​</a></h3><p>The naive view of a model API is &quot;prompt in, text out&quot; — apparently one knob: the prompt. Once engineered, &quot;what is seen this turn&quot; splits into at least five sub-problems, each with its own invariants: tokens have budget invariants, sources have priorities and invalidation conditions, history has storage and concurrency, repo conventions have nearest-wins and command truthfulness. <strong>Each sub-problem is independently acceptance-testable</strong> — that is the reason to split them.</p><h3 id="group-level-invariants-expanded-per-page-the-synopsis-here" tabindex="-1">Group-level invariants (expanded per page; the synopsis here) <a class="header-anchor" href="#group-level-invariants-expanded-per-page-the-synopsis-here" aria-label="Permalink to &quot;Group-level invariants (expanded per page; the synopsis here)&quot;">​</a></h3><ol><li><strong>Count before sending</strong>: any assembled request can be judged for overflow before it ships (→ <a href="./context-window.html">context-window</a> I1).</li><li><strong>Trimming must not break structure</strong>: system kept, tool pairs intact, eviction visible (→ I2 and <a href="./context-engineering.html">context-engineering</a>).</li><li><strong>Every source has a priority and an invalidation condition</strong>: assembly without priorities is arrival-order by another name (→ context-engineering).</li><li><strong>Commands must be real</strong>: assistants execute what AGENTS.md lists (→ <a href="./repo-context.html">repo-context</a>).</li></ol><h3 id="two-universal-stop-here-lines" tabindex="-1">Two universal &quot;stop here&quot; lines <a class="header-anchor" href="#two-universal-stop-here-lines" aria-label="Permalink to &quot;Two universal &quot;stop here&quot; lines&quot;">​</a></h3><ul><li>Attention math, KV cache, the four memory patterns → Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Chapter 15</a> (this group takes only the engineering implications).</li><li>Vendor window numbers, caching prices, token-counting endpoint fields → each vendor&#39;s docs on the day (this group maintains no number lists).</li></ul><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><h3 id="group-exit-criteria" tabindex="-1">Group exit criteria <a class="header-anchor" href="#group-exit-criteria" aria-label="Permalink to &quot;Group exit criteria&quot;">​</a></h3><ul><li>[ ] Rewrite a vague request into a four-element prompt that enters version control (prompt)</li><li>[ ] Compute a four-block token budget for a request; trim without severing tool pairs (context-window)</li><li>[ ] Assign priorities to multiple sources with reported eviction and stable sources in the prefix (context-engineering)</li><li>[ ] Build sessions for multi-turn chat: budget trimming, persistent recovery, concurrency guards (session-memory)</li><li>[ ] Land an AGENTS.md with real commands and correct layering for your repo (repo-context)</li></ul><h3 id="debug-runbooks-group-level-symptoms" tabindex="-1">Debug runbooks (group-level symptoms) <a class="header-anchor" href="#debug-runbooks-group-level-symptoms" aria-label="Permalink to &quot;Debug runbooks (group-level symptoms)&quot;">​</a></h3><h4 id="r1-routed-to-the-wrong-layer-editing-prompts-instead-of-trimming-the-window" tabindex="-1">R1 &quot;Routed to the wrong layer; editing prompts instead of trimming the window&quot; <a class="header-anchor" href="#r1-routed-to-the-wrong-layer-editing-prompts-instead-of-trimming-the-window" aria-label="Permalink to &quot;R1 &quot;Routed to the wrong layer; editing prompts instead of trimming the window&quot;&quot;">​</a></h4><p><strong>Symptom</strong>: multi-turn quality drops; the team ships three prompt revisions with no improvement. <strong>Evidence</strong>: the per-turn token curve still rises monotonically — the problem is not expression but budget. <strong>Action</strong>: return to <a href="./context-window.html">context-window</a> R1 per the symptom routing table; expression symptoms (instability, off-target) belong in <a href="./prompt.html">prompt</a>. <strong>Done when</strong>: failure samples are attributed (expression / budget / content / history / conventions) before action; the attribution is recorded in the PR.</p><h4 id="r2-the-gets-dumber-as-it-goes-localization-chain" tabindex="-1">R2 The &quot;gets dumber as it goes&quot; localization chain <a class="header-anchor" href="#r2-the-gets-dumber-as-it-goes-localization-chain" aria-label="Permalink to &quot;R2 The &quot;gets dumber as it goes&quot; localization chain&quot;">​</a></h4><p><strong>Symptom</strong>: answer quality clearly declines in the second half of long sessions. <strong>Evidence</strong>: check in order — is the token curve near the window (budget) → are retrieval chunks stale (content) → were key turns trimmed (history). <strong>Action</strong>: budget full → trim or compact; content stale → switch to JIT; history lost → adjust retention (see <a href="./context-window.html">context-window</a>, <a href="./context-engineering.html">context-engineering</a>, <a href="./session-memory.html">session-memory</a> respectively). <strong>Done when</strong>: similar sessions stop degrading monotonically with turns; the chain is written into the team&#39;s troubleshooting doc.</p><h4 id="r3-behavior-changes-with-every-assistant" tabindex="-1">R3 &quot;Behavior changes with every assistant&quot; <a class="header-anchor" href="#r3-behavior-changes-with-every-assistant" aria-label="Permalink to &quot;R3 &quot;Behavior changes with every assistant&quot;&quot;">​</a></h4><p><strong>Symptom</strong>: correct in Cursor, wrong deps in Claude Code; every newcomer steps on the same rake. <strong>Evidence</strong>: no AGENTS.md at the repo root, or commands that do not match reality. <strong>Action</strong>: land the file per <a href="./repo-context.html">repo-context</a> R1; monorepo exceptions use nested files. <strong>Done when</strong>: fresh sessions use the right commands on turn one; behavior is consistent across tools and teammates.</p><h3 id="anti-patterns-group-level" tabindex="-1">Anti-patterns (group level) <a class="header-anchor" href="#anti-patterns-group-level" aria-label="Permalink to &quot;Anti-patterns (group level)&quot;">​</a></h3><ul><li>Skipping the budget and piling on retrieval: more content, worse quality — rot does not vanish with a bigger window.</li><li>Fixing content problems with longer prompts: trim what should be trimmed; change sources that should be changed.</li><li>Assembly logic scattered in many places: concatenation that bypasses priorities and guards is a second source of truth.</li><li>Failures swallowed silently: eviction, trimming, and expiry must all be reported, or none of it is debuggable.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><h3 id="four-level-reading-route" tabindex="-1">Four-level reading route <a class="header-anchor" href="#four-level-reading-route" aria-label="Permalink to &quot;Four-level reading route&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Read</th><th>Why this order</th></tr></thead><tbody><tr><td>Beginner</td><td><a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview" target="_blank" rel="noreferrer">Anthropic prompt engineering overview</a></td><td><a href="https://developers.openai.com/api/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">OpenAI guide, context window section</a></td></tr><tr><td>Builder</td><td>The group&#39;s five pages in order + the <a href="./context-window.html">context-window fixture</a></td><td>A regression-checkable budget and assembly loop in hand</td></tr><tr><td>Operator</td><td>Both providers&#39; prompt caching and token counting docs</td><td><a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a></td></tr><tr><td>Researcher</td><td><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic: Effective context engineering</a></td><td><a href="https://research.trychroma.com/context-rot" target="_blank" rel="noreferrer">Chroma: Context Rot</a></td></tr></tbody></table><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Level</th><th>canonical URL</th><th>Use</th><th>Supports</th><th>Next</th></tr></thead><tbody><tr><td>The group&#39;s five topic pages</td><td>L1</td><td><a href="./prompt.html">prompt</a> · <a href="./context-window.html">context-window</a> · <a href="./context-engineering.html">context-engineering</a> · <a href="./session-memory.html">session-memory</a> · <a href="./repo-context.html">repo-context</a></td><td>Main path</td><td>—</td><td>Read in order</td></tr><tr><td>Anthropic context engineering</td><td>L1</td><td><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents</a></td><td>Mental model overview</td><td>Meta-principle / JIT / compaction / rot</td><td>Read the original</td></tr><tr><td>OpenAI prompt engineering</td><td>L1</td><td><a href="https://developers.openai.com/api/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">https://developers.openai.com/api/docs/guides/prompt-engineering</a></td><td>Official budget view</td><td>Windows measured in tokens</td><td>Read their Structured Outputs</td></tr><tr><td>Anthropic Context windows</td><td>L1</td><td><a href="https://platform.claude.com/docs/en/build-with-claude/context-windows" target="_blank" rel="noreferrer">https://platform.claude.com/docs/en/build-with-claude/context-windows</a></td><td>Window and billing basis</td><td>Input and output share the budget</td><td>Pair with token counting</td></tr><tr><td>agents.md</td><td>L1</td><td><a href="https://agents.md/" target="_blank" rel="noreferrer">https://agents.md/</a></td><td>Repo-level context convention</td><td>Format, nearest-wins, tool support</td><td>Land one for your repo</td></tr><tr><td>Chroma Context Rot</td><td>L4</td><td><a href="https://research.trychroma.com/context-rot" target="_blank" rel="noreferrer">https://research.trychroma.com/context-rot</a></td><td>Empirical decay</td><td>Long-context retrieval degradation</td><td>Read before designing long-document tasks</td></tr><tr><td>Learn LLM Chapter 15</td><td>L2</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/15-prompt-memory</a></td><td>Mechanism bridge</td><td>Attention / KV cache / four memory patterns</td><td>When you need the &quot;why&quot;</td></tr></tbody></table><p>(retrievedAt: 2026-09-01.)</p><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>This group&#39;s conclusions rest on the two vendors&#39; docs and Anthropic&#39;s engineering article as retrieved 2026-09-01; window numbers and caching prices drift — recheck within ≤ 6 months.</li><li>The five-topic split is this repo&#39;s pedagogical organization, serving each page&#39;s acceptance-testable exit; it is not an industry-standard taxonomy.</li><li>Open: no general formula for the context-rot knee (→ <a href="./context-window.html">context-window</a>); no public benchmark for compaction retention (→ <a href="./context-engineering.html">context-engineering</a>).</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>With the input side closed, how to build retrieval grounding → <a href="./../04-grounding/embeddings-retrieval.html">Embeddings and Retrieval</a>, <a href="./../04-grounding/rag.html">RAG</a>.</li><li>Executing actions → <a href="./../05-action/tool-calling.html">Tool Calling Contract</a>.</li><li>Budget and cost as operational metrics → <a href="./../08-production/cost-performance.html">Cost and Performance</a>.</li><li>Attention and memory mechanisms → Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">Chapter 15</a>.</li></ul>`,55)])])}const b=e(a,[["render",i]]);export{w as __pageData,b as default};
